using System;using System.IO;using System.Linq;using System.Text;using System.Windows;using System.Windows.Media.Media3D;using F=System.Windows.Forms;
namespace GearLab {
 static class PlacementTests {
  static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
  static bool Near(Vector3D a,Vector3D b){return(a-b).Length<1e-7;}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   for(int kind=0;kind<5;kind++){var p=Engine.Starter(kind==4?0:kind);if(kind==4)Engine.SetPreset(p,5);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Valid&&r.Model.Valid,"CAD "+kind);var original=ReleaseSupport.Serialize(p);string stepBefore=StepExportText(r,folder,"before-"+kind);
    using(var scene=new WpfScene()){scene.Root.Measure(new Size(900,650));scene.Root.Arrange(new Rect(0,0,900,650));scene.SetResult(r,false);var node=scene.Nodes.First(n=>n.Part.Role=="housing");string id=node.Part.Id;int builds=SceneMesher.Builds;var mesh=node.Frozen;scene.Select(id);var delta=new Vector3D(24,-13,35);Check(scene.SetOffset(id,delta),"set XYZ");Check(Near(scene.Offset(id),delta),"offset stored");
     for(int i=0;i<25;i++){double phase=i*.11;scene.UpdatePose(phase);var expected=node.Motion.At(phase,0);expected.Translate(delta);Check(node.Pose==expected,"motion plus world translation "+kind);}
     Check(SceneMesher.Builds==builds&&ReferenceEquals(node.Frozen,mesh),"move reuses mesh");var camera=scene.Camera.Target;double width=scene.Camera.Width;scene.SetOffset(id,delta*2);Check(scene.Camera.Target==camera&&scene.Camera.Width==width,"move preserves camera");scene.Hidden.Add(id);scene.RefreshVisibility();scene.SetOffset(id,delta);scene.Hidden.Clear();scene.RefreshVisibility();Check(node.Surface.Geometry!=null&&Near(scene.Offset(id),delta),"hide/show moved part");
     scene.SetExploded(true);var expectedExploded=node.Motion.At(scene.Phase,node.Index*2.5);expectedExploded.Translate(delta);Check(node.Pose==expectedExploded,"explode plus offset");scene.SetExploded(false);scene.SetMoveMode(true);scene.MoveAxis=-1;Check(scene.BeginPartDrag(id,new Point(50,50)),"start drag");var start=scene.Offset(id);scene.DragPart(new Point(150,110));Check(Near(scene.Offset(id)-start,scene.Camera.Right*(100*scene.Camera.Width/900)-scene.Camera.Up*(60*scene.Camera.Width/900)),"screen drag");scene.EndPartDrag(true);Check(Near(scene.Offset(id),start),"cancel drag");
     for(int axis=0;axis<3;axis++){scene.MoveAxis=axis;scene.BeginPartDrag(id,new Point(0,0));scene.DragPart(new Point(100,80));var d=scene.Offset(id)-start;Check((axis==0?Math.Abs(d.Y)+Math.Abs(d.Z):axis==1?Math.Abs(d.X)+Math.Abs(d.Z):Math.Abs(d.X)+Math.Abs(d.Y))<1e-8,"axis constraint "+axis);scene.EndPartDrag(true);}
     scene.Camera.Preset("Сверху");scene.MoveAxis=2;Check(scene.DragDelta(new Point(),new Point(100,50)).Length<1e-6,"camera parallel axis safe");scene.Camera.Preset("Изометрия");
     foreach(int axis in new[]{0,1,2}){double coordinate=axis==0?delta.X:axis==1?delta.Y:node.Frozen.Bounds.Z+delta.Z+node.Frozen.Bounds.SizeZ*.5;scene.ConfigureSection(axis,coordinate,false);Check(node.Surface.Geometry!=null||node.Cap.Geometry!=null,"moved section "+axis);if(axis==2&&node.Surface.Geometry!=null)Check(((MeshGeometry3D)node.Surface.Geometry).Bounds.Z+((MeshGeometry3D)node.Surface.Geometry).Bounds.SizeZ<=coordinate-delta.Z+1e-5,"Z clip uses moved local plane");}
     scene.ConfigureSection(-1,0,false);scene.Fit();scene.SavePng(Path.Combine(folder,"moved-"+kind+".png"),900,650);
     Check(!scene.SetOffset(id,new Vector3D(double.NaN,0,0))&&!scene.SetOffset(id,new Vector3D(10001,0,0))&&!scene.SetOffset("missing",delta),"reject invalid offsets");scene.SetResult(r,false);Check(Near(scene.Offset(id),delta),"same CAD preserves offsets");scene.ResetPlacements();Check(scene.Offset(id).Length==0,"reset all");scene.SetOffset(id,delta);var fresh=Engine.Calculate(p);fresh.Model=CadBuilder.Build(fresh);scene.SetResult(fresh,false);Check(scene.Offset(id).Length==0&&scene.SelectedId==null,"new geometry resets offsets and selection");
    }
    Check(original==ReleaseSupport.Serialize(p),"parameters unaffected");Check(stepBefore==StepExportText(r,folder,"after-"+kind),"STEP assembly unaffected");log.AppendLine("PASS kind "+kind+": XYZ/screen drag, axes, cancel, animation, hidden parts, explosion, clipping, mesh reuse, reset and original STEP.");
   }
   using(var host=new F.Form{Opacity=0,ShowInTaskbar=false,Width=1000,Height=800})using(var viewer=new GearViewerControl()){host.Controls.Add(viewer);host.Show();F.Application.DoEvents();var p=Engine.Starter(0);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);viewer.SetResult(r,false);var controls=VisibilityTests.Controls(viewer).ToArray();var tree=controls.OfType<F.TreeView>().Single();var leaf=tree.Nodes.Cast<F.TreeNode>().SelectMany(n=>n.Nodes.Cast<F.TreeNode>()).First();tree.SelectedNode=leaf;string id=(string)leaf.Tag;var input=controls.OfType<F.NumericUpDown>().Single(c=>c.AccessibleName=="Сдвиг детали X");Check(input.Enabled,"UI number enabled on selection");input.Value=27;Check(viewer.Scene.Offset(id).X==27,"UI numeric movement");typeof(SafeNumber).GetMethod("OnMouseWheel",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(input,new object[]{new F.MouseEventArgs(F.MouseButtons.None,0,0,0,-120)});Check(viewer.Scene.Offset(id).X==27,"wheel scroll does not change offset");var checkbox=controls.OfType<F.CheckBox>().Single(c=>c.AccessibleName=="Режим перемещения деталей");checkbox.Checked=true;Check(viewer.Scene.MoveParts,"UI move toggle");var axis=controls.OfType<F.ComboBox>().Single(c=>c.AccessibleName=="Ось перемещения детали");axis.SelectedIndex=3;Check(viewer.Scene.MoveAxis==2,"UI axis selection");controls.OfType<F.Button>().Single(b=>b.Text=="Вернуть деталь").PerformClick();Check(viewer.Scene.Offset(id).Length==0&&input.Value==0,"UI reset selected syncs fields");input.Value=15;controls.OfType<F.Button>().Single(b=>b.Text=="Вернуть все").PerformClick();Check(viewer.Scene.Offset(id).Length==0&&input.Value==0,"UI reset all");}
   log.AppendLine("PASS "+checks+" placement checks; native drag handlers share the tested placement path; toolbar/number/axis/reset controls exercised.");File.WriteAllText(Path.Combine(folder,"placement-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"placement-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
  static string StepExportText(Result r,string folder,string name){string file=Path.Combine(folder,name+".step");StepExport.Write(r.Model,file);return string.Join("\n",File.ReadAllLines(file).Where(l=>!l.StartsWith("FILE_NAME(")));}
 }
}
